export type CustomerWorkflowTranslationKey = (typeof customerWorkflowTemplateRows)[number][0];

const translators = createCustomerWorkflowClientTranslators(
  customerWorkflowExactTranslations,
  customerWorkflowTemplateRows,
);

export function customerWorkflowExactT(locale: LocaleCode, source: string) {
  return translators.exactT(locale, source);
}

export function customerWorkflowT(
  locale: LocaleCode,
  key: CustomerWorkflowTranslationKey,
  values: Record<string, string | number> = {},
) {
  return translators.t(locale, key, values);
}

export function customerPasswordErrorT(locale: LocaleCode, source: string) {
  return translateCustomerPasswordError(
    locale,
    source,
    customerWorkflowExactT,
    customerWorkflowT as CustomerWorkflowTemplateTranslator,
  );
}
